# owner: platform
"""Absence notices for parents."""

from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Short text notice listing a student's absent days."""
    all_marks = list(marks)
    for mark in all_marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id} given "
                f"with student {student.student_id}"
            )
    days = sorted(
        mark.day for mark in all_marks
        if mark.status == "absent"
    )
    if not days:
        raise ProjectError(
            f"no absences for {student.student_id}"
        )
    count = len(days)
    unit = "day" if count == 1 else "days"
    listed = ", ".join(stamp.isoformat() for stamp in days)
    name = f"{student.first_name} {student.last_name}"
    return (
        f"{name} missed {count} {unit}: {listed}"
    )
